```yaml
name: PR Title Validation
on:
  pull_request:
    types:
      - opened
      - edited
      - synchronize

jobs:
  validate-pr-title:
    runs-on: ubuntu-latest
    steps:
      - name: Validate PR Title
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo, number } = context.issue;
            const pr = await github.rest.pulls.get({
              owner,
              repo,
              pull_number: number
            });

            const title = pr.data.title;
            const body = pr.data.body || '';

            // Use environment variables to avoid bash injection
            process.env.PR_TITLE = title;
            process.env.PR_BODY = body;

            // Validate using JavaScript implementation
            const validatePRTitle = require('./scripts/validate-pr-title.js');
            const isValid = validatePRTitle(title, body);

            if (!isValid) {
              throw new Error('PR title does not match the required format. Please follow the conventional commit format.');
            }
